('cmuo2jvbl01d52gzm5eorpbtc', 'Energia leve', 'Plano 0', 'Energia', 1, 'Uma rotina curta para ativar o corpo sem entrar em modo treino.', 'Leve', NULL, NULL, 4, 25, 15, '["Respire fundo por 30 segundos","Gire ombros lentamente","Mexa mãos e tornozelos"]', '["Caminhe devagar","Solte braços","Beba água"]', 'Faça no seu ritmo. Pare se sentir dor, tontura ou desconforto e adapte os movimentos ao seu corpo.', 'Faça todos os movimentos sentado se preferir.', 15, '2026-09-30T12:15:54.706Z', '2026-09-30T12:15:54.706Z'),
('cmuo2jvbn01d62gzm827imtll', 'Foco antes da tarefa', 'Plano 0', 'Foco', 1, 'Uma sequência de respiração, postura e intenção para começar uma tarefa.', 'Leve', NULL, NULL, 3, 45, 10, '["Afaste notificações","Respire sem pressa","Escolha uma tarefa pequena"]', '["Nomeie a próxima ação","Organize o campo de visão","Comece por 2 minutos"]', 'Faça no seu ritmo. Pare se sentir dor, tontura ou desconforto e adapte os movimentos ao seu corpo.', 'Se estiver cansado, faça apenas a respiração e a escolha da próxima ação.', 15, '2026-09-30T12:15:54.707Z', '2026-09-30T12:15:54.707Z'),
('cmuo2jvbp01d72gzmpot8867e', 'Reset de estresse', 'Plano 0', 'Estresse', 2, 'Uma pausa guiada para baixar urgência antes de continuar o dia.', 'Leve', NULL, NULL, 4, 40, 20, '["Apoie os pés no chão","Solte ombros","Respire por 3 ciclos"]', '["Anote uma coisa que pode esperar","Beba água","Retome devagar"]', 'Faça no seu ritmo. Pare se sentir dor, tontura ou desconforto e adapte os movimentos ao seu corpo.', 'Mantenha tudo sentado e reduza qualquer movimento que incomode.', 15, '2026-09-30T12:15:54.709Z', '2026-09-30T12:15:54.709Z'),
('cmuo2jvbq01d82gzm2mdwp1tl', 'Alongamento de foco', 'Plano 0', 'Foco', 3, 'Alongamento simples para pescoço e ombros depois de muito tempo parado.', 'Leve', NULL, NULL, 5, 30, 15, '["Sente-se com apoio","Relaxe mandíbula","Respire sem pressa"]', '["Observe o corpo","Retome devagar","Escolha uma próxima ação pequena"]', 'Faça no seu ritmo. Pare se sentir dor, tontura ou desconforto e adapte os movimentos ao seu corpo.', 'Reduza amplitude e mantenha movimentos confortáveis.', 15, '2026-09-30T12:15:54.710Z', '2026-09-30T12:15:54.710Z'),
('cmuo2jvbs01d92gzmdrd9bora', 'Energia e rotina', 'Plano 0', 'Energia', 4, 'Movimento leve de baixo impacto para acordar o corpo sem pressão de performance.', 'Moderada', NULL, NULL, 5, 35, 25, '["Marcha leve","Mobilize quadril com apoio","Respire antes de começar"]', '["Alongue panturrilhas","Solte ombros","Beba água"]', 'Faça no seu ritmo. Pare se sentir dor, tontura ou desconforto e adapte os movimentos ao seu corpo.', 'Troque agachamentos por sentar e levantar de uma cadeira com apoio.', 25, '2026-09-30T12:15:54.712Z', '2026-09-30T12:15:54.712Z'),
('cmuo2jvbt01da2gzm343h4ocw', 'Yoga: base leve', 'Modalidades', 'Yoga', 5, 'Sequência curta de yoga leve para coluna, ombros e respiração.', 'Leve', NULL, NULL, 5, 45, 15, '["Respire de pé ou sentado","Gire ombros","Alongue braços sem forçar"]', '["Expire longo","Observe a postura","Volte com calma"]', 'Faça no seu ritmo. Pare se sentir dor, tontura ou desconforto e adapte os movimentos ao seu corpo.', 'Faça a sequência sentado se estiver cansado.', 15, '2026-09-30T12:15:54.713Z', '2026-09-30T12:15:54.713Z'),
('cmuo2jvbv01db2gzm8dyclgj0', 'Luta: sombra leve', 'Modalidades', 'Luta', 5, 'Rounds de sombra sem contato para coordenação, energia e foco.', 'Moderada', NULL, NULL, 6, 45, 30, '["Mobilize ombros","Faça base leve sem saltar","Respire antes do primeiro round"]', '["Solte braços","Alongue ombros","Respire até reduzir o ritmo"]', 'Sem contato e sem golpes explosivos. Pare se sentir dor, tontura ou desconforto.', 'Faça movimentos lentos de braço sentado ou troque por mobilidade de ombros.', 25, '2026-09-30T12:15:54.716Z', '2026-09-30T12:15:54.716Z'),
('cmuo2jvbx01dc2gzm2m6yrm4z', 'Jumping: baixo impacto', 'Modalidades', 'Jumping', 5, 'Sequência opcional com passos de baixo impacto para simular jumping sem excesso.', 'Moderada', NULL, NULL, 6, 30, 30, '["Aqueça tornozelos","Faça marcha no lugar","Teste step touch sem salto"]', '["Caminhe devagar","Alongue panturrilhas","Beba água"]', 'Evite se houver dor, tontura, lesão recente ou desconforto em joelhos, tornozelos ou coluna.', 'Alternativa sem impacto: step touch, marcha no lugar ou mobilidade leve.', 25, '2026-09-30T12:15:54.717Z', '2026-09-30T12:15:54.717Z'),
('cmuo2jvby01dd2gzm85u2tni5', 'Funcional em casa: base', 'Modalidades', 'Funcional em casa', 5, 'Rotina funcional sem equipamento, com movimentos controlados.', 'Moderada', NULL, NULL, 6, 35, 25, '["Marcha leve","Mobilize quadril","Faça agachamento curto com apoio"]', '["Alongue pernas","Solte ombros","Respire devagar"]', 'Faça no seu ritmo. Pare se sentir dor, tontura ou desconforto e adapte os movimentos ao seu corpo.', 'Use cadeira como apoio e reduza amplitude.', 25, '2026-09-30T12:15:54.719Z', '2026-09-30T12:15:54.719Z'),
('cmuo2jvc001de2gzmdg1mh25e', 'Mobilidade funcional', 'Modalidades', 'Mobilidade funcional', 5, 'Mobilidade de corpo inteiro para preparar treinos ou recuperar energia.', 'Leve', NULL, NULL, 5, 45, 15, '["Respire em pé","Mobilize pescoço sem forçar","Solte quadril com apoio"]', '["Alongue panturrilhas","Solte mãos","Observe o corpo"]', 'Faça no seu ritmo. Pare se sentir dor, tontura ou desconforto e adapte os movimentos ao seu corpo.', 'Faça tudo sentado se estiver com baixa energia.', 15, '2026-09-30T12:15:54.720Z', '2026-09-30T12:15:54.720Z'),
('cmuo2jvc101df2gzmx3xwh0d3', 'Corda iniciante opcional', 'Modalidades', 'Pular corda', 5, 'Primeira rotina opcional de corda com ritmo leve e pausas longas.', 'Moderada', 40, 70, 6, 20, 40, '["Aqueça tornozelos","Faça marcha no lugar","Teste a corda sem pressa"]', '["Caminhe devagar","Alongue panturrilhas","Respire e hidrate"]', 'Evite se houver dor, tontura, lesão recente, desconforto em joelho/tornozelo/coluna ou recomendação médica para evitar impacto.', 'Alternativa sem impacto: marcha no lugar, step touch, polichinelo sem salto ou mobilidade leve.', 30, '2026-09-30T12:15:54.722Z', '2026-09-30T12:15:54.722Z'),
('cmuo2jvc301dg2gzm8s0y539r', 'Corda base', 'Modalidades', 'Pular corda', 6, 'Rotina base para manter ritmo confortável, sem buscar intensidade alta.', 'Moderada', 70, 100, 8, 30, 30, '["Mobilize tornozelos e joelhos","Faça 1 minuto de marcha","Comece com saltos baixos"]', '["Caminhe devagar","Alongue panturrilhas","Faça respiração lenta"]', 'Evite se houver dor, tontura, lesão recente, desconforto em joelho/tornozelo/coluna ou recomendação médica para evitar impacto.', 'Alternativa sem impacto: marcha no lugar, step touch, polichinelo sem salto ou mobilidade leve.', 30, '2026-09-30T12:15:54.723Z', '2026-09-30T12:15:54.723Z'),
